package com.gwsheridan.worldsunwritten.release;

import com.google.gson.*;
import java.nio.file.*;
import java.security.MessageDigest;
import java.util.*;

/** Prepares immutable examples. Clean-instance validation remains a separate release check. */
public final class ReleaseCycle17Examples {
    private static final String MANIFEST="worldsunwritten.bundle.json";
    public static void main(String[] args)throws Exception{
        Path root=Path.of(args[0]);String version=args[3];if(!version.matches("[0-9][a-zA-Z0-9._-]{0,39}"))throw new IllegalArgumentException("Invalid release");
        try(var paths=Files.walk(root.resolve("examples"))){for(var path:paths.filter(p->p.toString().endsWith("-1.6.0.zip")&&p.getParent().getFileName().toString().equals("bundles")).sorted().toList()){var files=ReleaseExamples.read(path);metadata(files,version,null,null);String name=path.getFileName().toString().replace("-1.6.0.zip","");save(root,path.getParent().getParent().getFileName().toString(),name,version,files);}}
        var corridor=renamed(Path.of(args[1]),"corridor_regions",version,"Corridor regions","A connected corridor shares strict terrain, ore, decoration and structure filtering.");for(var path:new ArrayList<>(corridor.keySet()))if(path.endsWith(".json")){var json=ReleaseExamples.json(corridor.get(path));replace(json,Map.of("circle","river_path","diamond_circle","diamond_corridor","circle_building","corridor_building"));corridor.put(path,ReleaseExamples.bytes(json));}save(root,"corridor-regions","corridor-regions",version,corridor);
        var district=renamed(Path.of(args[2]),"structure_districts",version,"Structure districts","Weighted village buildings and outposts share deterministic exclusion, spacing and a named region.");for(int i=0;i<3;i++){String path="data/worldsunwritten_examples/worldgen/structure/district_"+i+".json";var definition=ReleaseExamples.json(district.get(path));if(i==2)definition.remove("themes");else{var themes=definition.getAsJsonObject("themes");var palettes=new JsonArray();palettes.add(themes.getAsJsonArray("palettes").get(i).deepCopy());themes.add("palettes",palettes);themes.remove("variants");}district.put(path,ReleaseExamples.bytes(definition));}save(root,"structure-districts","structure-districts",version,district);
        var base=ReleaseExamples.read(root.resolve("examples/creator-starters/bundles/skyblock-1.6.0.zip"));renamePreset(base,"reusable_skyblock");metadata(base,version,"Reusable Skyblock base","An immutable base with 64 personal islands, a native Nether and native End progression.");var bm=ReleaseExamples.json(base.get(MANIFEST));bm.addProperty("lock","partial");bm.addProperty("allow_structure_library",false);var editable=new JsonArray();editable.add("minecraft:overworld");bm.add("editable_dimensions",editable);base.put(MANIFEST,ReleaseExamples.bytes(bm));save(root,"reusable-presets","reusable-skyblock",version,base);
        String parentHash=hash(Files.readAllBytes(root.resolve("examples/reusable-presets/bundles/reusable-skyblock-"+version+".zip")));var baseline=ReleaseExamples.json(base.get(presetPath(bm.get("preset").getAsString())));var inheritance=new JsonObject();inheritance.addProperty("version",1);var parents=new JsonArray();var parent=new JsonObject();parent.add("preset",bm.get("preset").deepCopy());parent.addProperty("release",version);parent.addProperty("sha256",parentHash);parents.add(parent);inheritance.add("parents",parents);var policy=new JsonObject();for(String key:List.of("lock","options","editable_dimensions","required_mods","allow_structure_library"))policy.add(key,bm.get(key).deepCopy());inheritance.add("policy",policy);inheritance.add("baseline",baseline);var resources=new JsonObject();for(var entry:base.entrySet())if(entry.getKey().matches("data/[^/]+/(structure/.+\\.nbt|worldgen/structure/.+\\.json)"))resources.addProperty(entry.getKey(),hash(entry.getValue()));inheritance.add("resource_hashes",resources);
        for(boolean full:List.of(false,true)){var child=new TreeMap<String,byte[]>();base.forEach((k,v)->child.put(k,v.clone()));String name=full?"inherited-skyblock":"inherited-partial";renamePreset(child,name.replace('-','_'));metadata(child,version,full?"Locked inherited Skyblock":"Partially locked inherited Skyblock",full?"A self-contained child with 128 personal islands and a full generation lock.":"A self-contained child with 96 personal islands; only the Overworld remains editable.");var manifest=ReleaseExamples.json(child.get(MANIFEST));manifest.addProperty("format",2);manifest.add("inheritance",inheritance.deepCopy());if(full){manifest.addProperty("lock","full");manifest.remove("editable_dimensions");}var path=presetPath(manifest.get("preset").getAsString());var preset=ReleaseExamples.json(child.get(path));preset.getAsJsonObject("dimensions").getAsJsonObject("minecraft:overworld").getAsJsonObject("generator").getAsJsonObject("island").addProperty("personal_slots",full?128:96);child.put(path,ReleaseExamples.bytes(preset));child.put(MANIFEST,ReleaseExamples.bytes(manifest));save(root,"reusable-presets",name,version,child);}
        System.out.println("Prepared twenty-three example bundles and their source resources.");
    }
    private static SortedMap<String,byte[]> renamed(Path archive,String name,String version,String title,String description)throws Exception{var files=ReleaseExamples.read(archive);renamePreset(files,name);var replacements=new TreeMap<String,String>();for(var path:new ArrayList<>(files.keySet()))if(path.startsWith("data/validation/worldgen/structure/")){String old="validation:"+path.substring("data/validation/worldgen/structure/".length(),path.length()-5);replacements.put(old,"worldsunwritten_examples:"+old.substring(old.indexOf(':')+1));var definition=ReleaseExamples.json(files.remove(path));replace(definition,replacements);author(definition);files.put(path.replace("data/validation/","data/worldsunwritten_examples/"),ReleaseExamples.bytes(definition));}for(var path:new ArrayList<>(files.keySet()))if(path.endsWith(".json")){var json=ReleaseExamples.json(files.get(path));replace(json,replacements);files.put(path,ReleaseExamples.bytes(json));}metadata(files,version,title,description);return files;}
    private static void author(JsonElement element){if(element.isJsonObject()){var object=element.getAsJsonObject();if(object.has("author"))object.addProperty("author","GWSHERIDAN");for(var v:object.entrySet())author(v.getValue());}else if(element.isJsonArray())element.getAsJsonArray().forEach(ReleaseCycle17Examples::author);}
    private static void replace(JsonElement value,Map<String,String> replacements){if(value.isJsonObject())for(var entry:value.getAsJsonObject().entrySet()){if(entry.getValue().isJsonPrimitive()&&entry.getValue().getAsJsonPrimitive().isString()&&replacements.containsKey(entry.getValue().getAsString()))entry.setValue(new JsonPrimitive(replacements.get(entry.getValue().getAsString())));else replace(entry.getValue(),replacements);}else if(value.isJsonArray())for(var child:value.getAsJsonArray())replace(child,replacements);}
    private static void renamePreset(Map<String,byte[]> files,String name){var manifest=ReleaseExamples.json(files.get(MANIFEST));byte[] preset=files.remove(presetPath(manifest.get("preset").getAsString()));if(preset==null)throw new IllegalArgumentException("Missing preset");manifest.addProperty("preset","worldsunwritten_examples:"+name);files.put(presetPath(manifest.get("preset").getAsString()),preset);files.put(MANIFEST,ReleaseExamples.bytes(manifest));}
    private static String presetPath(String id){String[] parts=id.split(":",2);return "data/"+parts[0]+"/worldgen/world_preset/"+parts[1]+".json";}
    private static void metadata(Map<String,byte[]> files,String version,String title,String description){var manifest=ReleaseExamples.json(files.get(MANIFEST));manifest.addProperty("release",version);manifest.addProperty("author","GWSHERIDAN");if(title!=null)manifest.addProperty("title",title);if(description!=null)manifest.addProperty("description",description);files.put(MANIFEST,ReleaseExamples.bytes(manifest));var pack=ReleaseExamples.json(files.get("pack.mcmeta"));pack.getAsJsonObject("pack").addProperty("description",manifest.get("title").getAsString()+" for Worlds Unwritten "+version);files.put("pack.mcmeta",ReleaseExamples.bytes(pack));}
    private static String hash(byte[] bytes)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes));}
    private static void save(Path root,String directory,String name,String version,SortedMap<String,byte[]> files)throws Exception{ReleaseExamples.save(files,root.resolve("examples/"+directory+"/bundles/"+name+"-"+version+".zip"),root.resolve("examples/"+directory+"/"+name+"-"+version+"-source"));}
}
